 function interact(){if(!started)return;if(currentCar){currentCar.occupied=false;player.x=currentCar.x+Math.cos(currentCar.a+Math.PI/2)*34;player.y=currentCar.y+Math.sin(currentCar.a+Math.PI/2)*34;player.a=currentCar.a;currentCar=null;toast('نزلت من السيارة');return}let c=cars.filter(c=>!c.police).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(c&&Math.hypot(c.x-player.x,c.y-player.y)<70){currentCar=c;c.occupied=true;player.x=c.x;player.y=c.y;toast('السيارة جاهزة — انطلق!');if(missionStage===0){missionStage=1;target.x=2020;target.y=675;updateMission()}}else toast('اقترب من سيارة للركوب')}
